from pathlib import Path
root=Path(__file__).parent
css=(root/'app/static/styles.css').read_text()
html=r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NewsRadar · автономное демо</title><style>__CSS__
.offmap{height:clamp(360px,59vh,620px);background:#dfe8df;position:relative;border:1px solid #41596c;overflow:hidden;border-radius:17px}.offmap svg{width:100%;height:100%;position:absolute;inset:0}.offdot{position:absolute;display:grid;place-items:center;transform:translate(-50%,-50%);border:3px solid white;border-radius:50%;color:#fff;font-weight:800;box-shadow:0 5px 16px #0005;cursor:pointer;z-index:3}.offdot:focus-visible{outline-color:#0c1521}.offdot:hover{filter:brightness(1.12)}.offdot.ad{background:#8952df}.offdot.event{background:#159d71}.offdot.order{background:#cc962a}.offlayout{display:grid;grid-template-columns:1.5fr .9fr;gap:16px}.offcard{margin-top:12px}.nav{max-width:720px;margin-left:auto;margin-right:auto}.offapp{max-width:1060px;margin:auto}.offpill{display:inline-block;margin:4px 4px 4px 0;padding:4px 8px;border-radius:6px;font-size:11px;background:#243b55;color:#cedded}@media(max-width:770px){.offlayout{grid-template-columns:1fr}.offmap{height:55vh}.offapp{padding-bottom:78px}}
</style></head><body><div class="shell offapp"><header class="header"><div class="brand"><div class="logo">◉</div><div>NewsRadar<small>Senior за 3 дня</small></div></div><div class="header-actions"><span class="chip demo">OFFLINE ДЕМО</span><button class="btn ghost" id="edbtn">Редакция</button><button class="btn ghost" id="profilebtn">Профиль</button></div></header><nav class="nav" id="nav"><button data-page="send"><span>＋</span>Прислать новость</button><button data-page="map" class="active"><span>◉</span>Карта</button><button data-page="feed"><span>≡</span>Лента</button></nav><div id="main"></div><p class="footer">Автономная демонстрация: только вымышленные события, тестовый вход без SMS, нет отправки данных в сеть. Для настоящего API запустите проект из архива.</p></div><div id="modalCover" class="auth-cover hidden"><div class="modal"><div class="row between"><h2 id="modalTitle">Вход</h2><button class="btn ghost" onclick="closeModal()">✕</button></div><div id="modalBody"></div></div></div><div id="toast" role="status" aria-live="polite"></div><script>
const seed=[{id:1,title:'Возможно изменение маршрута автобуса №7',summary:'Нужна ссылка на официальное расписание или объявление перевозчика.',topic:'Транспорт',lat:55.752,lon:37.618,dx:26,dy:36,status:'order',question:'Подойдёт официальный документ или уже имеющееся фото объявления.',popularity:30,promoted:false,draft:1},{id:2,title:'Открытие выставки городской фотографии',summary:'Организаторы подтвердили программу мероприятия.',topic:'Культура',dx:70,dy:33,status:'published',popularity:210,promoted:false,draft:1},{id:3,title:'Концерт — рекламная афиша',summary:'Партнёрское событие с видеотизером (пример рекламной карточки).',topic:'Афиша',dx:61,dy:67,status:'published',popularity:45,promoted:true,draft:1},{id:4,title:'Уточняется режим работы спорткомплекса',summary:'Нет официального подтверждения информации об изменении графика.',topic:'Город',dx:36,dy:72,status:'order',question:'Нужно официальное объявление или документ.',popularity:12,promoted:false,draft:1},{id:5,title:'Новый мастер-класс по робототехнике',summary:'Сообщество опубликовало анонс встречи.',topic:'Технологии',dx:74,dy:78,status:'review',popularity:6,promoted:false,draft:1}];
let events=JSON.parse(localStorage.getItem('nr_off_events')||'null')||seed;let responses=JSON.parse(localStorage.getItem('nr_off_responses')||'[]');let user=localStorage.getItem('nr_off_phone')||'';let credits=Number(localStorage.getItem('nr_off_credits')||'0');let page='map',selected=1,ad=true,radius=10;
function save(){localStorage.setItem('nr_off_events',JSON.stringify(events));localStorage.setItem('nr_off_responses',JSON.stringify(responses));localStorage.setItem('nr_off_credits',String(credits));}
function q(id){return document.getElementById(id)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notify(s){q('toast').textContent=s;q('toast').className='show';setTimeout(()=>q('toast').className='',4000)}
function modal(title,body){q('modalTitle').textContent=title;q('modalBody').innerHTML=body;q('modalCover').classList.remove('hidden')}
function closeModal(){q('modalCover').classList.add('hidden')}
function login(next){modal('Вход по номеру телефона',`<p class="sub">Только для демонстрации: SMS не отправляется, телефон хранится в вашем браузере.</p><div class="field"><label>Номер (можно тестовый)</label><input id="phone" placeholder="+79990000000" type="tel"/></div><div class="field" style="margin-top:10px"><label>Тестовый код: 123456</label><input id="code" inputmode="numeric" placeholder="123456"/></div><button class="btn primary" style="margin-top:14px" id="oklogin">Войти</button>`);q('oklogin').onclick=()=>{if(!/^\+[1-9]\d{9,14}$/.test(q('phone').value)||q('code').value!=='123456'){notify('Введите тестовый номер и код 123456');return}user=q('phone').value;localStorage.setItem('nr_off_phone',user);closeModal();notify('Демо-вход выполнен');if(next)next();else render()}}
function tab(name){page=name;document.querySelectorAll('#nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));render()}
function eventBadge(e){return e.promoted?'<span class="tag ad">Реклама</span>':`<span class="tag ${e.status}">${e.status==='order'?'Требует проверки':e.status==='published'?'Проверено редактором':e.status==='review'?'Редакторская проверка':'Отклонено'}</span>`}
function mapPage(){let visible=events.filter(e=>['order','published'].includes(e.status)&&(!e.promoted||ad));let e=visible.find(x=>x.id===selected)||visible[0];let markers=visible.map(x=>{let r=Math.min(47,19+Math.log2(1+x.popularity)*2+(x.promoted?12:0));return `<button aria-label="${esc(x.title)}" title="${esc(x.title)}" onclick="selected=${x.id};render()" class="offdot ${x.promoted?'ad':x.status==='order'?'order':'event'}" style="width:${r}px;height:${r}px;left:${x.dx}%;top:${x.dy}%;${selected===x.id?'outline:3px solid #16263a;':''}">${x.promoted?'★':x.status==='order'?'?':'●'}</button>`}).join('');const road=`<svg viewBox="0 0 700 530" preserveAspectRatio="none" aria-hidden="true"><rect width="700" height="530" fill="#dce6df"/><g stroke="white" stroke-width="17">${[25,108,184,267,342,424,500].map(y=>`<path d="M0 ${y} L700 ${y-15}"/>`).join('')}${[40,150,275,400,530,660].map(x=>`<path d="M${x} 0 L${x-18} 530"/>`).join('')}</g><path d="M530 -15 Q380 250 580 550" fill="none" stroke="#b1d4e2" stroke-width="33"/></svg>`;return `<div class="row between wrap" style="margin-bottom:15px"><div><h1 class="section-title">Карта событий</h1><p class="sub">Маркеры на карте, без параллельной ленты</p></div><label class="switch"><input type="checkbox" id="adBox" ${ad?'checked':''} onchange="ad=this.checked;render()"> Реклама</label></div><div class="offlayout"><div><div class="offmap">${road}${markers}</div><p class="footnote">Условная схема города. Популярность влияет на размер, рекламные метки отличаются и отключаются.</p></div><aside class="panel">${e?`${eventBadge(e)}<h2 style="margin-top:13px">${esc(e.title)}</h2><p class="sub">${esc(e.summary)}</p><span class="offpill">${esc(e.topic)}</span><span class="offpill">Интерес: ${e.popularity}</span><span class="offpill">${e.promoted?'★ Реклама':e.status==='order'?'? Нужны доказательства':'✓ Проверено'}</span>${e.status==='order'?`<p class="sub" style="margin-top:18px">${esc(e.question)}</p><div class="row wrap"><button class="btn green" onclick="evidence(${e.id},'confirm')">Подтвердить</button><button class="btn ghost" onclick="evidence(${e.id},'refute')">Опровергнуть</button></div>`:e.promoted?'<div class="notice">Интерактивная афиша: здесь может быть видеоанонс, программа и ссылка. Это пример рекламы.</div>':''}`:'<p>В этом слое событий нет.</p>'}<div class="notice" style="margin-top:16px">Непроверенные публикации на карту автоматически не попадают.</div></aside></div>`}
function feedPage(){const items=events.filter(e=>e.status==='order');return `<h1 class="section-title">Лента запросов на проверку</h1><p class="sub">Отдельно от карты. Редакция ищет подтверждения или опровержения. Только вымышленные события.</p><div class="row" style="margin-bottom:16px"><label class="muted tiny">Радиус демонстрации</label><select class="btn" onchange="radius=Number(this.value);render()">${[2,5,10,25,50].map(n=>`<option value="${n}" ${n===radius?'selected':''}>${n} км</option>`).join('')}</select></div>${(radius<5?items.slice(0,1):items).map(e=>`<div class="story">${eventBadge(e)}<h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p><div class="notice">Нужно уточнить: ${esc(e.question||'Источник и обстоятельства')}</div><p class="tiny muted">Вознаграждение: до 30 демо-баллов после принятия редактором</p><div class="buttons"><button class="btn green" onclick="evidence(${e.id},'confirm')">Подтвердить</button><button class="btn ghost" onclick="evidence(${e.id},'refute')">Опровергнуть</button></div></div>`).join('')||'<div class="empty">Нет открытых запросов.</div>'}`}
function evidence(id,kind){if(!user){login(()=>evidence(id,kind));return}const e=events.find(x=>x.id===id);modal(kind==='confirm'?'Подтверждение':'Опровержение',`<p class="sub">${esc(e.title)}</p><div class="field"><label>Какими сведениями вы располагаете?</label><textarea id="textProof" minlength="8" placeholder="Напишите подтверждение, опровержение или ссылку на документ"></textarea></div><div class="field" style="margin-top:12px"><label>Дополнительно: фото или видео</label><input id="proofFile" type="file" accept="image/*,video/*"></div><p class="footnote">В автономном демо имя файла сохранится только в браузере, а сам файл никуда не передаётся.</p><button id="submitProof" class="btn primary">Передать редактору</button>`);q('submitProof').onclick=()=>{const text=q('textProof').value;if(text.length<8){notify('Напишите хотя бы 8 символов');return}responses.push({id:Date.now(),event_id:id,kind,text,filename:q('proofFile').files[0]?.name||'',status:'pending'});save();closeModal();notify('Доказательство передано в демо-очередь редактора');render()}}
function sendPage(){return `<div class="panel" style="max-width:650px"><h1>Прислать новость</h1><p class="sub">Новое сообщение сначала проходит AI-сортировку и проверку человеком. Оно не появится на карте без решения редактора.</p><form id="sendform" class="form"><div class="field"><label>Заголовок</label><input id="newTitle" required minlength="8" placeholder="Что произошло?"></div><div class="field"><label>Описание</label><textarea id="newDesc" required minlength="8" placeholder="Что известно, откуда информация?"></textarea></div><div class="field"><label>Тема</label><select id="newTopic"><option>Город</option><option>Транспорт</option><option>Культура</option><option>Спорт</option><option>Технологии</option><option>Афиша</option></select></div><div class="field"><label>Фото или видео (демо)</label><input id="newFile" type="file" accept="image/*,video/*"></div><button class="btn primary">Отправить</button></form><div class="notice warn" style="margin-top:16px">Не нужно специально ездить к происшествиям. Используйте только информацию и материалы, которыми уже располагаете.</div></div>`}
function profilePage(){return `<div class="panel"><h1>Профиль</h1>${user?`<p>Телефон: ${esc(user)}</p><p>Баллы: <strong>${credits}</strong></p><p>Отправленных материалов: ${responses.length}</p><button class="btn ghost" onclick="user='';localStorage.removeItem('nr_off_phone');render()">Выйти</button>`:`<p class="sub">Для отправки потребуется тестовая регистрация. Чтение карты и ленты открыто без входа.</p><button class="btn primary" onclick="login()">Войти по телефону</button>`}<div class="notice" style="margin-top:20px">Состояние автономной демонстрации хранится в localStorage только этого браузера.</div></div>`}
function editorPage(){return `<h1 class="section-title">Редакторская панель · Демонстрация</h1><p class="sub">Нейросеть оценивает тему/важность (в автономном макете оценки имитируются). Редактор принимает решения. Ордер выполняется через отдельную ленту.</p><div class="stats"><div class="stat"><b>${events.filter(e=>e.status==='review').length}</b><small>На проверке</small></div><div class="stat"><b>${events.filter(e=>e.status==='order').length}</b><small>Ордеров</small></div><div class="stat"><b>${responses.filter(r=>r.status==='pending').length}</b><small>Новых ответов</small></div></div><div class="editor-grid"><div class="panel"><h2>Новости</h2>${events.map(e=>`<div class="editor-item" onclick="editEvent(${e.id})">${eventBadge(e)}<b>${esc(e.title)}</b><small>Черновик v${e.draft||1} · ${esc(e.topic)}</small></div>`).join('')}</div><div class="panel" id="selectedEditor"><p class="sub">Выберите новость слева</p></div></div><div class="panel" style="margin-top:14px"><h2>Ответы на ордера</h2>${responses.map(r=>{const e=events.find(x=>x.id===r.event_id);return `<div class="story"><span class="tag ${r.status==='pending'?'review':'published'}">${esc(r.status)}</span><h3>${esc(e?.title||'')}</h3><p>${esc(r.kind==='refute'?'Опровержение: ':'Подтверждение: ')}${esc(r.text)}</p>${r.filename?`<p class="tiny">Файл (только название): ${esc(r.filename)}</p>`:''}${r.status==='pending'?`<button class="btn green" onclick="review(${r.id},true)">Принять</button> <button class="btn danger" onclick="review(${r.id},false)">Отклонить</button>`:''}</div>`}).join('')||'<p class="sub">Ответов пока нет</p>'}</div><div class="row" style="margin-top:15px"><button class="btn ghost" onclick="resetDemo()">Сбросить демо</button></div>`}
function editEvent(id){const e=events.find(x=>x.id===id),panel=q('selectedEditor');panel.innerHTML=`${eventBadge(e)}<h2 style="margin-top:12px">${esc(e.title)}</h2><p class="sub">${esc(e.summary)}</p><div class="notice">AI-анализ в этом автономном демо имитируется. Нет автоматического подтверждения достоверности.</div><p>Версия черновика: <b>${e.draft||1}</b></p><div class="field"><label>Задание на проверку</label><textarea id="orderQuestion" placeholder="Какое подтверждение или опровержение требуется?">${esc(e.question||'')}</textarea></div><div class="row wrap" style="margin-top:12px"><button class="btn danger" onclick="decide(${id},'rejected')">Отклонить</button><button class="btn green" onclick="decide(${id},'published')">Одобрить</button><button class="btn primary" onclick="decide(${id},'order')">Создать ордер</button></div>`}
function decide(id,status){const e=events.find(x=>x.id===id);if(status==='order'){const question=q('orderQuestion')?.value.trim();if(!question){notify('Укажите, что именно необходимо проверить');return}e.question=question}e.status=status;save();render();notify('Редакторское решение сохранено (демо).')}
function review(id,accepted){const r=responses.find(x=>x.id===id);r.status=accepted?'accepted':'rejected';if(accepted){const e=events.find(x=>x.id===r.event_id);e.status='review';e.draft=(e.draft||1)+1;credits+=30}save();render();notify(accepted?'Ордер выполнен, новый черновик возвращён редактору':'Ответ отклонён')}
function resetDemo(){if(confirm('Сбросить локальные демонстрационные новости и ответы?')){events=JSON.parse(JSON.stringify(seed));responses=[];credits=0;save();render();}}
function render(){q('nav').style.display=page==='editor'||page==='profile'?'none':'';q('main').innerHTML=page==='map'?mapPage():page==='feed'?feedPage():page==='send'?sendPage():page==='profile'?profilePage():editorPage();if(page==='send'){q('sendform').onsubmit=ev=>{ev.preventDefault();if(!user){login(()=>tab('send'));return}const title=q('newTitle').value,summary=q('newDesc').value;if(title.length<8||summary.length<8){notify('Нужно больше информации');return}events.unshift({id:Date.now(),title,summary,topic:q('newTopic').value,dx:48,dy:45,status:'review',popularity:0,promoted:false,draft:1});save();notify('Новость создана и направлена редактору');tab('profile')}}}
q('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>tab(b.dataset.page));q('profilebtn').onclick=()=>tab('profile');q('edbtn').onclick=()=>tab('editor');render();
</script></body></html>'''
html=html.replace('__CSS__',css)
(root.parent/'NewsRadar_автономное_демо.html').write_text(html)
